from pathlib import Path
import base64, hashlib, subprocess

def blob_sha(raw):
    return hashlib.sha1(b"blob " + str(len(raw)).encode() + b"\0" + raw).hexdigest()

p = Path("src/App.vue")
assert blob_sha(p.read_bytes()) == 'd01e0697e32b18bf191b107bd5b7d2fd763ec3e3', "Unexpected source version"
patch = base64.b64decode('')
subprocess.run(["git", "apply", "--check"], input=patch, check=True)
subprocess.run(["git", "apply"], input=patch, check=True)
assert blob_sha(p.read_bytes()) == '87309c9fd29524347b31caa84cb79a858986f718', "App source differs from the tested production build"
for path, expected in {'api/fabric-shopping-operations.js': 'fe5c3481b6028c99df729de5d9b064559fde979f', 'server/fabric-shopping-operations.cjs': '99c07ff2b05d45c8729750329351e43c74a354cd', 'src/components/FabricShoppingOperations.vue': '47761eb4a11c9423d78b0495c5d2457701a1e67b', 'src/fabric-shopping-api.js': 'd1077392753b2b45db76ebdf3a8d364eaf5899bd', 'src/fabric-shopping-operations.js': 'db06f7a36553f1da83b6d0f8432e290e365aec05', 'tests/fabric-shopping-operations.test.cjs': '69d6d52cd659eead1278aea3dcaefa1026d63f5b'}.items():
    assert blob_sha(Path(path).read_bytes()) == expected, "Supporting file differs from tested source: " + path
Path("tools/apply-fabric-operations.py").unlink()
Path(".github/workflows/apply-fabric-operations.yml").unlink()
print("All 7 file hashes match the tested production build.")
